259	    @Override
260	    @Transactional
261	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
262	        if (owner.isNew()) {
263	            LocalDate effectiveDate = owner.getRegistrationDate() != null
264	                ? owner.getRegistrationDate()
265	                : LocalDate.now();
266	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
267	            if (owner.getHouseholdId() == null) {
268	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
269	            }
270	            if (owner.getCustomerCode() == null) {
271	                owner.setCustomerCode(generateCustomerCode(owner));
272	            }
273	            if (owner.getNamesakeCount() == null) {
274	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
275	            }
276	            if (owner.getPossibleDuplicate() == null) {
277	                // A declared household member is not a suspected duplicate; otherwise flag it against
278	                // any existing member of the same household it collides with.
279	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
280	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
281	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
282	            }
283	        }
284	        ownerRepository.save(owner);
285	        decorateWithHouseholdMemberCount(owner);
286	    }
287	
288	    /**
289	     * Count the existing owners (before this create) that share the given first and last name,
290	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
291	     */
292	    private int countNamesakes(String firstName, String lastName) {
293	        if (firstName == null || lastName == null) {
294	            return 0;
295	        }
296	        return (int) ownerRepository.findAll().stream()
297	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
298	                && lastName.equalsIgnoreCase(owner.getLastName()))
299	            .count();
300	    }
301	
302	    /**
303	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
304	     * canonical region derived from the owner's postcode (falling back to the city-to-region
305	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
306	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
307	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}).
308	     * <p>
309	     * If the computed code collides with an existing owner's {@code customerCode}, it is
310	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
311	     * makes it unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
312	     */
313	    private String generateCustomerCode(Owner owner) {
314	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
315	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
316	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
317	        String base = region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
318	
319	        Set<String> existingCodes = ownerRepository.findAll().stream()
320	            .map(Owner::getCustomerCode)
321	            .filter(Objects::nonNull)
322	            .collect(Collectors.toSet());
323	        if (!existingCodes.contains(base)) {
324	            return base;
325	        }
326	        int n = 2;
327	        while (existingCodes.contains(base + "-" + n)) {
328	            n++;
329	        }
330	        return base + "-" + n;
331	    }
332	
333	    /**
334	     * Count the existing owners whose city matches the given city, compared case-insensitively,
335	     * used by the per-city capacity rule ({@link #isCityAtCapacity}).
336	     */
337	    private long countOwnersInCity(String city) {
338	        if (city == null) {
339	            return 0L;
340	        }
341	        return ownerRepository.findAll().stream()
342	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
343	            .count();
344	    }
345	
346	    @Override
347	    @Transactional(readOnly = true)
348	    public boolean isCityAtCapacity(String city) throws DataAccessException {
349	        return countOwnersInCity(city) >= CITY_CAPACITY;
350	    }
351	
352	    @Override
353	    @Transactional(readOnly = true)
354	    public boolean isDailyRegistrationAtCapacity() throws DataAccessException {
355	        return countRegisteredToday() >= DAILY_CAPACITY;
356	    }
357	
358	    @Override
359	    @Transactional(readOnly = true)
360	    public boolean isBulkSignupDay() throws DataAccessException {
361	        return countRegisteredToday() > BULK_SIGNUP_THRESHOLD;
362	    }
363	
364	    /**
365	     * Count the owners whose registration date equals today's business day, used by the
366	     * daily create-limit and bulk-signup rules.
367	     */
368	    private long countRegisteredToday() {
369	        LocalDate businessDay = toBusinessDay(LocalDate.now());
370	        return ownerRepository.findAll().stream()
371	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
372	            .count();
373	    }
374	
375	    /** Fixed public holidays the business-day roll skips. */
376	    private static final Set<LocalDate> HOLIDAYS = Set.of(
377	        LocalDate.parse("2026-01-01"),
378	        LocalDate.parse("2026-01-26"),
379	        LocalDate.parse("2026-04-25"),
380	        LocalDate.parse("2026-12-25"),
381	        LocalDate.parse("2026-12-28"));
382	
383	    /**
384	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
385	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
386	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
387	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
388	     * derived from it (such as the membership number's year segment) and the per-day create-limit
389	     * all use the adjusted business day.
390	     */
391	    private static LocalDate toBusinessDay(LocalDate date) {
392	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
393	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
394	            || HOLIDAYS.contains(date)) {
395	            date = date.plusDays(1);
396	        }
397	        return date;
398	    }
399	
400	    @Override
401	    @Transactional(readOnly = true)
402	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
403	        String identityKey = owner.getIdentityKey();
404	        return ownerRepository.findAll().stream()
405	            .filter(existing -> existing != owner)
406	            .filter(existing -> !existing.isDeleted())
407	            .map(Owner::getIdentityKey)
408	            .anyMatch(identityKey::equals);
409	    }
410	
411	    /**
412	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
413	     * duplicate of, or {@code null} when there is none. A possible duplicate belongs to an existing
414	     * owner's household (same computed {@code householdId}, i.e. same last name and postcode) while
415	     * carrying a different telephone, so it is not a hard duplicate (its identity key is unique) but is
416	     * worth flagging. When several existing owners match, the one with the lowest id is returned so the
417	     * result is deterministic. Computed once, at creation, to drive the read-only
418	     * {@code possibleDuplicate}/{@code possibleDuplicateOf} fields.
419	     */
420	    private Integer findPossibleDuplicateOf(Owner owner) {
421	        String householdId = owner.getHouseholdId();
422	        if (householdId == null) {
423	            return null;
424	        }
425	        return ownerRepository.findAll().stream()
426	            .filter(existing -> existing != owner && existing.getId() != null)
427	            .filter(existing -> !existing.isDeleted())
428	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
429	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
430	            .map(Owner::getId)
431	            .min(Integer::compareTo)
432	            .orElse(null);
433	    }
434	
435	    @Override
436	    @Transactional(readOnly = true)
437	    public boolean isHouseholdInUse(Owner owner) throws DataAccessException {
438	        String householdId = owner.getHouseholdId() != null
439	            ? owner.getHouseholdId()
440	            : householdIdFor(owner.getLastName(), owner.getPostcode());
441	        return ownerRepository.findAll().stream()
442	            .filter(existing -> existing != owner && existing.getId() != null)
443	            .filter(existing -> !existing.isDeleted())
444	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
445	    }
446	
447	    @Override
448	    @Transactional(readOnly = true)
449	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
450	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
451	        return Sha256Hex.upperHexPrefix(key, 12);
452	    }
453	
454	    /**
455	     * Normalizes a household field (the last name) for duplicate comparison by trimming,
456	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
457	     * spaced but equivalent values compare equal.
458	     */
459	    private static String normalizeHouseholdValue(String value) {
460	        if (value == null) {
461	            return "";
462	        }
463	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
464	    }
465	
466	    /**
467	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
468	     * owners that share its {@code householdId}. Owners without a household id are left at a count
469	     * of zero.
470	     *
471	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
472	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
473	     */
474	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
475	        if (!owners.isEmpty()) {
476	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
477	                .filter(owner -> owner.getHouseholdId() != null)
478	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
479	            for (Owner owner : owners) {
480	                long size = owner.getHouseholdId() == null
481	                    ? 0L
482	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
483	                owner.setHouseholdMemberCount((int) size);
484	            }
485	        }
486	        return result;
487	    }
488	
489	    /**
490	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
491	     */
492	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
493	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
494	    }
495	
496	    @Override
497	    @Transactional(readOnly = true)
498	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
499	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
500	        return decorateWithHouseholdMemberCount(owners, owners);
501	    }
502	
503	    @Override
504	    @Transactional(readOnly = true)
505	    public Collection<Visit> findVisitsByPetId(int petId) {
506	        return visitRepository.findByPetId(petId);
507	    }
508	
509	    @Override
510	    @Transactional(readOnly = true)
511	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
512	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
513	    }
514	
515	    private <T> T findEntityById(Supplier<T> supplier) {
516	        try {
517	            return supplier.get();
518	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
519	            // Just ignore not found exceptions for Jdbc/Jpa realization
520	            return null;
521	        }
522	    }
523	
524	}
